-- AD10 CHECK (read-only): one row per rule, ok must be true on every row. Run through ad-sql-run.sh after AD10.sql.
SELECT 'the three case tables have forced RLS and desk_app has no right on them' AS rule, (SELECT bool_and(relrowsecurity AND relforcerowsecurity) FROM pg_class WHERE oid IN ('desk.fadm_escalation'::regclass,'desk.fadm_escalation_event'::regclass,'desk.fadm_escalation_outbox'::regclass)) AND NOT has_table_privilege('desk_app','desk.fadm_escalation','select') AND NOT has_table_privilege('desk_app','desk.fadm_escalation_event','select') AND NOT has_table_privilege('desk_app','desk.fadm_escalation_outbox','select')
UNION ALL SELECT 'cases and events are append-only (frozen triggers)', (SELECT count(*) FROM pg_trigger WHERE tgrelid IN ('desk.fadm_escalation'::regclass,'desk.fadm_escalation_event'::regclass) AND tgname LIKE '%frozen%') = 4
UNION ALL SELECT 'the event hash chain is computed by a trigger', EXISTS (SELECT 1 FROM pg_trigger WHERE tgrelid='desk.fadm_escalation_event'::regclass AND tgname='fadm_escalation_event_chain')
UNION ALL SELECT 'the request id is unique (idempotent)', EXISTS (SELECT 1 FROM pg_index WHERE indrelid='desk.fadm_escalation'::regclass AND indisunique AND indkey::text = (SELECT attnum::text FROM pg_attribute WHERE attrelid='desk.fadm_escalation'::regclass AND attname='request_id'))
UNION ALL SELECT 'the outbox has a partial index on pending rows', EXISTS (SELECT 1 FROM pg_indexes WHERE schemaname='desk' AND indexname='fadm_escalation_outbox_pending_i' AND indexdef LIKE '%WHERE%')
UNION ALL SELECT 'only create, list and chain-verify are granted to desk_app; claim and mark are not (founder-side phase)', has_function_privilege('desk_app','desk.fadm_escalation_create(uuid,text,text,text,text,text,text,text,text)','execute') AND has_function_privilege('desk_app','desk.fadm_escalation_list(uuid,text)','execute') AND has_function_privilege('desk_app','desk.fadm_escalation_chain_verify()','execute') AND NOT has_function_privilege('desk_app','desk.fadm_escalation_outbox_claim(int)','execute') AND NOT has_function_privilege('desk_app','desk.fadm_escalation_outbox_mark(bigint,boolean)','execute')
UNION ALL SELECT 'no AD10 helper or trigger function is executable by PUBLIC', NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='desk' AND p.proname IN ('fadm_escalation_no','fadm_escalation_event_chain','fadm_escalation_frozen','fadm_escalation_target_min','fadm_escalation_outbox_claim','fadm_escalation_outbox_mark') AND has_function_privilege('public', p.oid, 'execute'))
UNION ALL SELECT 'the reason, priority and flag are closed lists and the note refuses money and promise words', (SELECT count(*) FROM pg_constraint WHERE conrelid='desk.fadm_escalation'::regclass AND contype='c') >= 6
UNION ALL SELECT 'the case event chain verifies', desk.fadm_escalation_chain_verify()
UNION ALL SELECT 'the main ledger hash chain still verifies', desk.fadm_ledger_verify();
